const token = $input.item.json.access_token;
const org = '82d61b63-ca61-4705-b62d-02266001c6bc';
const project = '28c96091-b86b-438f-b702-7f2f368423d8';
const useCase = $('Webhook').item.json.body.use_case;
const industry = $('Webhook').item.json.body.industry;
const meetingType = $('Webhook').item.json.body.meeting_type;
const anthropicKey = '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';

// Fetch templates
const templatesRes = await this.helpers.request({
  method: 'GET',
  url: `https://api.prod.alltrue-be.com/v1/llm-firewall/templates?organization=${org}&project=${project}`,
  headers: { Authorization: `Bearer ${token}` },
  json: true
});

// Fetch rules
const rulesRes = await this.helpers.request({
  method: 'GET',
  url: 'https://api.prod.alltrue-be.com/v1/llm-firewall/rules',
  headers: { Authorization: `Bearer ${token}` },
  json: true
});

const rules = rulesRes.llm_firewall_rules.map(r => ({
  rule_type: r.rule_type,
  category: r.category,
  description: r.description
}));

// Call Claude
const claudeRes = await this.helpers.request({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': anthropicKey,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-6',
    max_tokens: 2048,
    system: 'You are an Atlas AI Security demo advisor. Return structured JSON only — no prose outside the JSON.\n\nRespond with this exact structure:\n{"existing_matches":[{"template_name":"...","match_score":0,"match_reason":"...","rules_included":["..."]}],"custom_recommendation":{"suggested_name":"...","description":"...","rules":[{"rule_type":"...","reason":"..."}]},"recommendation":"existing or custom","recommendation_reason":"one sentence"}',
    messages: [{
      role: 'user',
      content: `CUSTOMER USE CASE:\n${useCase}\n\nINDUSTRY: ${industry}\nMEETING TYPE: ${meetingType}\n\nEXISTING TEMPLATES:\n${JSON.stringify(templatesRes, null, 2)}\n\nAVAILABLE RULES:\n${JSON.stringify(rules, null, 2)}\n\nIf an existing template scores 75+, recommend it. Otherwise recommend a custom build with 3-8 rules.`
    }]
  })
});

const parsed = JSON.parse(claudeRes);
const text = parsed.content[0].text;

let result;
try {
  const match = text.match(/```json\n?([\s\S]*?)\n?```/) || text.match(/({[\s\S]*})/);
  result = JSON.parse(match ? match[1] : text);
} catch(e) {
  result = { error: 'Parse failed', raw: text };
}

return {
  json: {
    ...result,
    use_case: useCase,
    industry,
    meeting_type: meetingType
  }
};
